using Godot;
using System;
using System.Linq;
using System.Threading.Tasks;
public partial class MigrationScene {
 async Task BlueprintSystemsChecks(){var original=game;var oldPosition=player.Position;var oldCamera=camera.GlobalTransform;double oldShot=shotClock,oldReload=reloadClock;string oldTab=researchTab;int oldSelected=selectedBuild;try{
  game=new ExpeditionGame(ProjectSettings.GlobalizePath("user://tests/blueprints-"+Guid.NewGuid()+".json")){NoDiskSave=true};game.Craft.Materials=Enumerable.Repeat(500,7).ToArray();game.Craft.BenchTier=game.Craft.UnlockedTier=5;game.Skills.Crafting.Level=5;game.Craft.ResearchPoints=1000;game.Career.Level=2;
  researchTab="Defenses";researchChoice=Array.FindIndex(ExpeditionRecipe.All,r=>r.Kind=="build"&&BuildDefinition.All[r.Result].Tab=="Defenses"&&r.Tier==2);game.Craft.ResearchPoints=1;MigrationChecks.Assert(!game.Research(researchChoice)&&game.Craft.ResearchPoints==1,"Insufficient research points cannot unlock");game.Craft.ResearchPoints=1000;game.Career.Level=2;ShowResearchTree();var unlock=menu.FindChildren("*","Button",true,false).OfType<Godot.Button>().First(b=>b.Text=="RESEARCH / 2 POINTS");unlock.EmitSignal(Godot.Button.SignalName.Pressed);MigrationChecks.Assert(game.Craft.ResearchPoints==998&&game.Knows(ExpeditionRecipe.All[researchChoice]),"Research tab button spends points once");var select=menu.FindChildren("*","Button",true,false).OfType<Godot.Button>().First(b=>b.Text=="SELECT FOR PLACEMENT");select.EmitSignal(Godot.Button.SignalName.Pressed);MigrationChecks.Assert(buildMode&&selectedBuild==ExpeditionRecipe.All[researchChoice].Result&&!paused,"Blueprint selection enters live building mode");buildMode=false;
  BuildingUsabilityChecks();
  MigrationChecks.Assert(BuildDefinition.All.Length>=80&&ExpeditionRecipe.All.Count(r=>r.Kind=="build")==BuildDefinition.All.Length,"Every buildable has a blueprint");foreach(var recipe in ExpeditionRecipe.All.OrderBy(r=>r.Tier)){game.Craft.ResearchFocus.Clear();if(!game.Knows(recipe))MigrationChecks.Assert(game.Research(Array.IndexOf(ExpeditionRecipe.All,recipe)),"Research reachable / "+recipe.Name);}
  GD.Print($"BLUEPRINT TOTALS / {BuildDefinition.All.Length} buildables, {ExpeditionRecipe.All.Length} recipes, {ExpeditionItemDefinition.All().Count} models");int points=game.Craft.ResearchPoints;game.AwardResearch("check/once",20);game.AwardResearch("check/once",20);MigrationChecks.Assert(game.Craft.ResearchPoints==points+20,"No research award farming");game.Skills.Die();MigrationChecks.Assert(game.Craft.ResearchPoints==points+20,"Death keeps research points");
  BuildPiece Add(string function,int tier=0,double x=0,double z=12){int kind=Array.FindIndex(BuildDefinition.All,d=>d.Function==function&&(tier==0||d.Tier==tier));MigrationChecks.Assert(kind>=0,"Functional blueprint / "+function);var p=new BuildPiece{Kind=kind,Id=Guid.NewGuid().ToString("N"),X=x,Z=z,Y=game.World.Height(x,z),Health=BuildDefinition.All[kind].Durability,Stock=new int[11]};game.Building.Pieces.Add(p);return p;}
  var chest=Add("storage");player.Position=Ground(0,12);int wood=game.Craft.Materials[0];UseBlueprint(chest.Id+"|deposit|0");MigrationChecks.Assert(chest.Stock[0]==10&&game.Craft.Materials[0]==wood-10,"Storage deposits real resources");UseBlueprint(chest.Id+"|withdraw|0");MigrationChecks.Assert(chest.Stock[0]==0&&game.Craft.Materials[0]==wood,"Storage withdrawals conserve resources");game.Building.Pieces.Clear();
  var generator=Add("power",4);UseBlueprint(generator.Id+"|fuel");MigrationChecks.Assert(generator.Charge==600,"Generator fuel conversion");var water=Add("water",4,3,12);TickBaseSystems(120);MigrationChecks.Assert(water.Stock[8]==4&&generator.Charge==480,"Powered water production / fuel use");player.Position=Ground(3,12);int drinks=game.Craft.Water;UseBlueprint(water.Id+"|collect");MigrationChecks.Assert(game.Craft.Water==drinks+4&&water.Stock[8]==0,"Collect production once");
  var medical=Add("medical",4,3,12);game.Save.X=3;game.Save.Z=12;MigrationChecks.Assert(game.MedicalRecovery==2,"Powered medical recovery");game.Life.Wounds.Add(new ExpeditionWound{Patched=true,Recovery=1200});game.Life.TickWounds(60);MigrationChecks.Assert(game.Life.Wounds[0].Recovery==1140,"Medical station preserves 20-minute bandage rule");var door=Add("door",4,3,12);UseBlueprint(door.Id+"|door");MigrationChecks.Assert(door.Open,"Powered door interaction");generator.Charge=0;UseBlueprint(door.Id+"|door");MigrationChecks.Assert(door.Open,"Powered door cannot operate without power");
  var copy=Json.Read<System.Collections.Generic.List<BuildPiece>>(Json.Write(game.Building.Pieces));MigrationChecks.Assert(copy.Any(p=>p.Id==door.Id&&p.Open)&&copy.Any(p=>p.Id==generator.Id&&p.Charge==0),"World station state roundtrip");game.Building.Pieces.Clear();var turret=Add("turret",3,20,12);turret.Stock[10]=3;SyncStructures();AddEnemy("blueprint/target",20,6,1);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);var enemy=infected.FirstOrDefault();MigrationChecks.Assert(enemy!=null,"Defense target fixture");double before=enemy.Hp;defenseClock=0;TickBaseSystems(1);MigrationChecks.Assert(turret.Stock[10]==2&&(!infected.Contains(enemy)||enemy.Hp<before),"Turret spends ammunition and damages hostile");ClearEnemies();game.Building.Pieces.Clear();
  var vehicle=Add("vehicle",5,0,12);player.Position=Ground(0,12);vehicleDrivers[vehicle.Id]=0;SyncStructures();await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);double previous=vehicle.Z;game.Clock+=1;DriveBlueprint(vehicle.Id+"|0|1");MigrationChecks.Assert(vehicle.Z<previous,"Vehicle drive moves a persistent structure");vehicleDrivers.Clear();game.Building.Pieces.Clear();
  game.Craft.Weapon=6;game.Craft.Arrows=2;game.Craft.Ammo=2;game.Craft.Reserve=30;player.Position=Ground(0,12);camera.Position=new(0,1.65f,0);camera.LookAt(Ground(0,7)+Vector3.Up);SyncStructures();AddEnemy("blueprint/bow",0,7,1);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);enemy=infected.First();before=enemy.Hp;shotClock=reloadClock=0;Shoot();for(int flight=0;flight<30;flight++)TickPrimitiveCombat(.02);MigrationChecks.Assert(game.Craft.Arrows==1&&game.Craft.Reserve==30&&enemy.Hp<before,"Bow consumes arrows and damages target");ClearEnemies();game.Craft.Weapon=7;game.Craft.Ammo=2;AddEnemy("blueprint/shotgun",0,7,1);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);enemy=infected.First();enemy.Hp=100;shotClock=0;Shoot();MigrationChecks.Assert(game.Craft.Ammo==1&&!infected.Contains(enemy),"Shotgun resolves pellet damage with one ammunition cost");ClearEnemies();
  game.Craft.Researched.Clear();game.Craft.ResearchVersion=0;game.Craft.BenchTier=3;game.Normalize();MigrationChecks.Assert(ExpeditionRecipe.All.Where(r=>r.Tier<=3).All(game.Knows),"Existing workshop progress grandfathered into research");GD.Print("PASS / all blueprints researchable, award deduplication/death retention, storage conservation, fueled power, water collection, medical timing, door power gates, station saves, defense ammunition, driveable rover and legacy unlock migration");
 }finally{ClearEnemies();CloseMenu();game=original;player.Position=oldPosition;camera.GlobalTransform=oldCamera;SyncStructures();baseVisualPower=false;shotClock=oldShot;reloadClock=oldReload;researchTab=oldTab;selectedBuild=oldSelected;buildMode=false;}}
}
